const items = $input.all();

function getPayload(item) {
  let data = item.json;

  // Caso 1: ya viene directamente con time/datetime
  if (data.time || data.datetime) {
    return data;
  }

  // Caso 2: viene dentro de json
  if (data.json) {
    if (typeof data.json === "string") {
      return JSON.parse(data.json);
    }
    return data.json;
  }

  // Caso 3: viene dentro de message
  if (data.message) {
    if (typeof data.message === "string") {
      return JSON.parse(data.message);
    }
    return data.message;
  }

  // Caso 4: viene dentro de content
  if (data.content) {
    if (typeof data.content === "string") {
      return JSON.parse(data.content);
    }
    return data.content;
  }

  // Caso 5: viene dentro de body
  if (data.body) {
    if (typeof data.body === "string") {
      return JSON.parse(data.body);
    }
    return data.body;
  }

  throw new Error(
    "No encuentro el mensaje real. Campos recibidos: " + Object.keys(data).join(", ")
  );
}

const result = items.map(item => {
  const data = getPayload(item);

  const datetime = data.datetime || data.time;

  if (!datetime) {
    throw new Error(
      "Falta el campo time/datetime. Campos recibidos: " + Object.keys(data).join(", ")
    );
  }

  const [datePart, timePart] = datetime.split("T");

  if (!datePart || !timePart) {
    throw new Error(`Formato de fecha inválido: ${datetime}`);
  }

  const [year, month, day] = datePart.split("-");
  const [hour] = timePart.split(":");

  // Quitamos time para no duplicar con datetime
  const { time, ...dataWithoutTime } = data;

  return {
    json: {
      datetime: datetime,
      date: datePart,
      year: Number(year),
      month: Number(month),
      day: Number(day),
      hour: Number(hour),
      ...dataWithoutTime
    }
  };
});

return result;

const item = $input.first().json;

const year = item.year;
const month = String(item.month).padStart(2, '0');
const day = String(item.day).padStart(2, '0');
const hour = String(item.hour).padStart(2, '0');

const path = `weather/${year}/${month}/${day}/weather${item.date}_${hour}.json`;

const content = JSON.stringify(item, null, 2);

return [
  {
    json: {
      path: path
    },
    binary: {
      data: {
        data: Buffer.from(content, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName: `weather${item.date}_${hour}.json`
      }
    }
  }
];
